	validStages  = map[string]bool{"preschool": true, "low": true, "mid": true, "high": true}
	validPlat    = map[string]bool{"tv": true, "phone": true, "pad": true, "miniapp": true}
)

// Options 是身份服务配置。
type Options struct {
