package question_test

import (
	"bytes"
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"testing"
	"time"

	_ "github.com/jackc/pgx/v5/stdlib"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/pressly/goose/v3"
	"github.com/redis/go-redis/v9"
	"golang.org/x/crypto/bcrypt"

	"github.com/roma007/OpenQuizGo/internal/admin"
	"github.com/roma007/OpenQuizGo/internal/httpapi"
	"github.com/roma007/OpenQuizGo/internal/question"
	"github.com/roma007/OpenQuizGo/migrations"
)

func TestQuestionWorkflow(t *testing.T) {
	dbURL := os.Getenv("TEST_DATABASE_URL")
	redisURL := os.Getenv("TEST_REDIS_URL")
	if dbURL == "" || redisURL == "" {
		t.Skip("TEST_DATABASE_URL / TEST_REDIS_URL not set")
	}

	ctx := context.Background()
	prepareDB(t, dbURL)
	rdb := prepareRedis(t, redisURL)
	defer func() { _ = rdb.Close() }()

	pool, err := pgxpool.New(ctx, dbURL)
	if err != nil {
		t.Fatalf("pool: %v", err)
	}
	defer pool.Close()

	createAdmin(t, pool, "admin", "admin12345", "super_admin")
	createAdmin(t, pool, "editor", "editor12345", "editor")

	logger := slog.New(slog.NewTextHandler(io.Discard, nil))
	adminSvc := admin.NewService(pool, rdb, "test-secret-0123456789-0123456789", 8*time.Hour, logger)
	questionSvc := question.New(pool, logger)

	server := httptest.NewServer(httpapi.New(httpapi.Deps{
		Logger:    logger,
		DB:        pool,
		Redis:     rdb,
		Admin:     adminSvc,
		Questions: questionSvc,
		Version:   "test",
		Env:       "test",
	}))
	defer server.Close()

	c := &client{t: t, base: server.URL + "/v1"}
	adminToken := c.login("admin", "admin12345")

	var created question.Question
	c.expect(http.MethodPost, "/admin/questions", validQuestion("1+1=?"), adminToken, http.StatusCreated, &created)
	if created.Status != "draft" || created.Version != 1 {
		t.Fatalf("unexpected created question: %+v", created)
	}

	c.expect(http.MethodPost, "/admin/questions/"+created.ID+"/publish", nil, adminToken, http.StatusConflict, nil)
	c.expect(http.MethodPost, "/admin/questions/"+created.ID+"/submit-review", nil, adminToken, http.StatusOK, nil)
	c.expect(http.MethodPost, "/admin/questions/"+created.ID+"/review",
		map[string]bool{"approve": true}, adminToken, http.StatusOK, nil)
	c.expect(http.MethodPost, "/admin/questions/"+created.ID+"/publish", nil, adminToken, http.StatusOK, nil)
	c.expect(http.MethodPut, "/admin/questions/"+created.ID, validQuestion("2+2=?"), adminToken, http.StatusConflict, nil)

	bad := validQuestion("bad")
	bad["category"] = "core"
	bad["subject"] = "fun"
	c.expect(http.MethodPost, "/admin/questions", bad, adminToken, http.StatusUnprocessableEntity, nil)

	var listed question.ListResult
	c.expect(http.MethodGet, "/admin/questions?subject=math&stage=low&difficulty=2&type=choice",
		nil, adminToken, http.StatusOK, &listed)
	if listed.Total != 1 || listed.Items[0].Status != "online" {
		t.Fatalf("unexpected list: %+v", listed)
	}

	importBody := map[string]any{"questions": importQuestions(100)}
	var imported question.ImportResult
	c.expect(http.MethodPost, "/admin/questions/import", importBody, adminToken, http.StatusOK, &imported)
	if imported.Imported != 100 {
		t.Fatalf("imported = %d, want 100", imported.Imported)
	}

	invalid := map[string]any{"questions": []any{map[string]any{
		"subject": "math", "category": "core", "stage": "low",
		"difficulty": 9, "type": "choice", "stem": "bad", "options": []any{}, "answer": []any{},
	}}}
	c.expect(http.MethodPost, "/admin/questions/import", invalid, adminToken, http.StatusUnprocessableEntity, nil)

	editorToken := c.login("editor", "editor12345")
	c.expect(http.MethodPost, "/admin/questions/"+created.ID+"/publish", nil, editorToken, http.StatusForbidden, nil)

	var audit []question.AuditEntry
	c.expect(http.MethodGet, "/admin/audit?limit=20", nil, adminToken, http.StatusOK, &audit)
	if len(audit) == 0 {
		t.Fatal("audit log is empty")
	}
}

type client struct {
	t    *testing.T
	base string
}

func (c *client) login(username, password string) string {
	c.t.Helper()
	var resp struct {
		Token string `json:"token"`
	}
	c.expect(http.MethodPost, "/admin/auth/login",
		map[string]string{"username": username, "password": password}, "", http.StatusOK, &resp)
	if resp.Token == "" {
		c.t.Fatalf("login %s returned empty token", username)
	}
	return resp.Token
}

func (c *client) expect(method, path string, body any, token string, want int, out any) {
	c.t.Helper()

	var reader io.Reader
	if body != nil {
		payload, err := json.Marshal(body)
		if err != nil {
			c.t.Fatalf("marshal: %v", err)
		}
		reader = bytes.NewReader(payload)
	}
	req, err := http.NewRequest(method, c.base+path, reader)
	if err != nil {
		c.t.Fatalf("new request: %v", err)
	}
	req.Header.Set("Content-Type", "application/json")
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		c.t.Fatalf("%s %s: %v", method, path, err)
	}
	defer resp.Body.Close()
	payload, _ := io.ReadAll(resp.Body)
	if resp.StatusCode != want {
		c.t.Fatalf("%s %s status = %d, want %d, body = %s", method, path, resp.StatusCode, want, payload)
	}
	if out != nil && len(payload) > 0 {
		if err := json.Unmarshal(payload, out); err != nil {
			c.t.Fatalf("decode: %v, body = %s", err, payload)
		}
	}
}

func validQuestion(stem string) map[string]any {
	return map[string]any{
		"subject": "math", "category": "core", "stage": "low",
		"grade_tag": "g2", "difficulty": 2, "type": "choice", "stem": stem,
		"options": []map[string]string{{"id": "a", "text": "1"}, {"id": "b", "text": "2"}},
		"answer":  []string{"b"},
	}
}

func importQuestions(n int) []map[string]any {
	items := make([]map[string]any, 0, n)
	for i := 0; i < n; i++ {
		items = append(items, map[string]any{
			"subject": "math", "category": "core", "stage": "low",
			"difficulty": i%5 + 1, "type": "choice",
			"stem":    fmt.Sprintf("导入题 %d", i+1),
			"options": []map[string]string{{"id": "a", "text": "1"}, {"id": "b", "text": "2"}},
			"answer":  []string{"a"},
		})
	}
	return items
}

func prepareDB(t *testing.T, url string) {
	t.Helper()
	db, err := sql.Open("pgx", url)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer func() { _ = db.Close() }()

	goose.SetBaseFS(migrations.FS)
	if err := goose.SetDialect("postgres"); err != nil {
		t.Fatalf("dialect: %v", err)
	}
	if err := goose.Up(db, "."); err != nil {
		t.Fatalf("migrate: %v", err)
	}
	if _, err := db.Exec(`truncate table question, topic_pack, audit_log, admin_user cascade`); err != nil {
		t.Fatalf("truncate: %v", err)
	}
}

func prepareRedis(t *testing.T, url string) *redis.Client {
	t.Helper()
	opts, err := redis.ParseURL(url)
	if err != nil {
		t.Fatalf("redis url: %v", err)
	}
	client := redis.NewClient(opts)
	if err := client.FlushDB(context.Background()).Err(); err != nil {
		t.Fatalf("flush redis: %v", err)
	}
	return client
}

func createAdmin(t *testing.T, pool *pgxpool.Pool, username, password, role string) {
	t.Helper()
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.MinCost)
	if err != nil {
		t.Fatalf("hash: %v", err)
	}
	ctx := context.Background()
	var userID string
	if err := pool.QueryRow(ctx, `
		insert into admin_user (username, password_hash, display_name)
		values ($1, $2, $1) returning id`, username, string(hash)).Scan(&userID); err != nil {
		t.Fatalf("insert admin: %v", err)
	}
	if _, err := pool.Exec(ctx, `
		insert into admin_user_role (user_id, role_id)
		select $1, id from admin_role where code = $2`, userID, role); err != nil {
		t.Fatalf("assign role: %v", err)
	}
}

package quiz

import "time"

// Rule 是组卷所需的规则子集。
type Rule struct {
	UnlockMinutes  int                `json:"unlock_minutes"`
	PassThreshold  float64            `json:"pass_threshold"`
	SubjectWeight  map[string]float64 `json:"subject_weight"`
	FunRatioCap    int                `json:"fun_ratio_cap"`
	FunEnabled     bool               `json:"fun_enabled"`
	WeightPreset   string             `json:"weight_preset,omitempty"`
}

// SelectRequest 是组卷请求。
type SelectRequest struct {
	ChildID      string `json:"child_id"`
	Stage        string `json:"stage"`
	GradeTag     string `json:"grade_tag"`
	Rule         Rule   `json:"rule"`
	Seed         int64  `json:"seed"`
	MaxQuestions int    `json:"max_questions"`
}

// Selected 是被选中的题目。
type Selected struct {
	QuestionID string `json:"question_id"`
	Subject    string `json:"subject"`
	Stage      string `json:"stage"`
	Type       string `json:"type"`
	Difficulty int    `json:"difficulty"`
	Repeated   bool   `json:"repeated"`
}

// Result 是组卷结果。
type Result struct {
	Total           int            `json:"total"`
	Quota           map[string]int `json:"quota"`
	Selected        []Selected     `json:"selected"`
	MaxScore        float64        `json:"max_score"`
	DifficultyTarget int           `json:"difficulty_target"`
	Warnings        []string       `json:"warnings,omitempty"`
	Seed            int64          `json:"seed"`
}

// Error 是组卷业务错误。
type Error struct {
	Status   int
	Code     string
	Message  string
	Warnings []string
}

func (e *Error) Error() string { return e.Message }

func newError(status int, code, message string) *Error {
	return &Error{Status: status, Code: code, Message: message}
}

// PreviewResponse 便于管理端 dry-run 查看。
type PreviewResponse struct {
	Result
	GeneratedAt time.Time `json:"generated_at"`
}

package quiz

import (
	"context"
	"fmt"

	"github.com/jackc/pgx/v5/pgxpool"
)

type repository struct {
	pool *pgxpool.Pool
}

func newRepository(pool *pgxpool.Pool) *repository {
	return &repository{pool: pool}
}

// Candidate 是候选题目。
type Candidate struct {
	ID         string
	Subject    string
	Stage      string
	Type       string
	Difficulty int
}

// pool 返回某学科在给定学段的在线题目；excludeRecent 为 true 时排除孩子近 30 天做过的题。
func (r *repository) pool(ctx context.Context, childID, subject string, stages []string, excludeRecent bool, limit int) ([]Candidate, error) {
	var childArg any
	if childID != "" && excludeRecent {
		childArg = childID
	}

	const query = `
		select q.id, q.subject_code, q.stage_code, q.type_code, q.difficulty
		from question q
		where q.status = 'online'
		  and q.subject_code = $1
		  and q.stage_code = any($2)
		  and ($3::uuid is null or not exists (
		      select 1 from answer_log a
		      where a.child_id = $3::uuid
		        and a.question_id = q.id
		        and a.answered_at > now() - interval '30 days'))
		limit $4`

	rows, err := r.pool.Query(ctx, query, subject, stages, childArg, limit)
	if err != nil {
		return nil, fmt.Errorf("query pool: %w", err)
	}
	defer rows.Close()

	items := make([]Candidate, 0, limit)
	for rows.Next() {
		var c Candidate
		if err := rows.Scan(&c.ID, &c.Subject, &c.Stage, &c.Type, &c.Difficulty); err != nil {
			return nil, err
		}
		items = append(items, c)
	}
	return items, rows.Err()
}

// childStage 读取孩子学段；childID 为空时返回空。
func (r *repository) childStage(ctx context.Context, childID string) (stage, grade string, err error) {
	if childID == "" {
		return "", "", nil
	}
	err = r.pool.QueryRow(ctx, `
		select stage_code, coalesce(grade_tag, '')
		from child_profile where id = $1`, childID).Scan(&stage, &grade)
	return stage, grade, err
}

// difficultyStats 返回孩子近 30 天各难度的正确率。
func (r *repository) difficultyStats(ctx context.Context, childID string) (map[int]float64, error) {
	if childID == "" {
		return map[int]float64{}, nil
	}
	rows, err := r.pool.Query(ctx, `
		select difficulty, count(*) as attempts,
		       sum(case when a.is_correct then 1 else 0 end)::float / count(*) as rate
		from answer_log a
		join question q on q.id = a.question_id
		where a.child_id = $1 and a.answered_at > now() - interval '30 days'
		group by difficulty`, childID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	stats := map[int]float64{}
	for rows.Next() {
		var difficulty, attempts int
		var rate float64
		if err := rows.Scan(&difficulty, &attempts, &rate); err != nil {
			return nil, err
		}
		if attempts >= 5 {
			stats[difficulty] = rate
		}
	}
	return stats, rows.Err()
}

package quiz

import (
	"context"
	"fmt"
	"log/slog"
	"math"
	"math/rand"
	"sort"
	"strings"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

const (
	maxSessionQuestions = 12
	defaultPoolLimit    = 2000
)

var (
	stageRanks = map[string]int{"preschool": 0, "low": 1, "mid": 2, "high": 3}
	stageOrder = map[string][]string{
		"preschool": {"preschool", "low", "mid", "high"},
		"low":       {"low", "preschool", "mid", "high"},
		"mid":       {"mid", "low", "high", "preschool"},
		"high":      {"high", "mid", "low", "preschool"},
	}
	validStages = map[string]bool{"preschool": true, "low": true, "mid": true, "high": true}
)

// Service 是组卷服务。
type Service struct {
	repo   *repository
	logger *slog.Logger
}

// New 构造组卷服务。
func New(pool *pgxpool.Pool, logger *slog.Logger) *Service {
	return &Service{repo: newRepository(pool), logger: logger}
}

// Select 按规则组卷。
func (s *Service) Select(ctx context.Context, req SelectRequest) (Result, error) {
	stage, grade := req.Stage, req.GradeTag
	if req.ChildID != "" {
		childStage, childGrade, err := s.repo.childStage(ctx, req.ChildID)
		if err != nil {
			return Result{}, newError(404, "CHILD_NOT_FOUND", "孩子档案不存在")
		}
		stage, grade = childStage, childGrade
	}
	stage = strings.TrimSpace(stage)
	if !validStages[stage] {
		return Result{}, newError(422, "VALIDATION_ERROR", "学段不合法")
	}
	if err := validateRule(req.Rule); err != nil {
		return Result{}, err
	}

	seed := req.Seed
	if seed == 0 {
		seed = time.Now().UnixNano()
	}
	rng := rand.New(rand.NewSource(seed))

	stats, err := s.repo.difficultyStats(ctx, req.ChildID)
	if err != nil {
		return Result{}, err
	}
	target := targetDifficulty(stage, grade, stats)

	maxQuestions := maxSessionQuestions
	if req.MaxQuestions > 0 && req.MaxQuestions < maxQuestions {
		maxQuestions = req.MaxQuestions
	}
	n, err := sessionSize(req.Rule, maxQuestions)
	if err != nil {
		return Result{}, err
	}

	subjectWeights := make(map[string]float64)
	maxWeight := 0.0
	for subject, weight := range req.Rule.SubjectWeight {
		if subject == "fun" || weight <= 0 {
			continue
		}
		subjectWeights[subject] = weight
		if weight > maxWeight {
			maxWeight = weight
		}
	}
	if len(subjectWeights) == 0 {
		return Result{}, newError(422, "VALIDATION_ERROR", "至少需要一个学科权重")
	}

	funSlots := 0
	if req.Rule.FunEnabled && req.Rule.FunRatioCap > 0 && req.Rule.SubjectWeight["fun"] > 0 {
		funSlots = min(req.Rule.FunRatioCap, max(1, n-1))
	}
	subjectSlots := n - funSlots
	quota := allocate(subjectWeights, subjectSlots)

	selected := make([]Selected, 0, n)
	chosen := map[string]bool{}
	warnings := make([]string, 0)
	addWarning := func(w string) {
		for _, existing := range warnings {
			if existing == w {
				return
			}
		}
		warnings = append(warnings, w)
	}

	stages := stageOrder[stage]
	primaryRank := stageRanks[stage]

	for subject, count := range quota {
		if err := s.fillSubject(ctx, req.ChildID, subject, stages, primaryRank,
			target, count, rng, chosen, &selected, addWarning); err != nil {
			return Result{}, err
		}
	}

	if funSlots > 0 {
		funStages := []string{"preschool", "low"}
		if stage == "mid" || stage == "high" {
			funStages = []string{"mid", "high"}
		}
		if err := s.fillSubject(ctx, req.ChildID, "fun", funStages, -1,
			target, funSlots, rng, chosen, &selected, addWarning); err != nil {
			return Result{}, err
		}
	}

	// 配额未满时，按权重从高到低再分配。
	if len(selected) < n {
		ordered := subjectsByWeight(subjectWeights)
		for pass := 0; pass < 2 && len(selected) < n; pass++ {
			progress := false
			for _, subject := range ordered {
				if len(selected) >= n {
					break
				}
				need := n - len(selected)
				before := len(selected)
				if err := s.fillSubject(ctx, req.ChildID, subject, stages, primaryRank,
					target, need, rng, chosen, &selected, addWarning); err != nil {
					return Result{}, err
				}
				if len(selected) > before {
					progress = true
				}
			}
			if !progress {
				break
			}
			addWarning("quota_redistributed")
		}
	}

	rng.Shuffle(len(selected), func(i, j int) {
		selected[i], selected[j] = selected[j], selected[i]
	})

	score := 0.0
	actual := map[string]int{}
	for _, item := range selected {
		score += req.Rule.SubjectWeight[item.Subject]
		actual[item.Subject]++
	}

	result := Result{
		Total:            len(selected),
		Quota:            actual,
		Selected:         selected,
		MaxScore:         round2(score),
		DifficultyTarget: target,
		Warnings:         warnings,
		Seed:             seed,
	}
	if len(selected) < 3 || score < req.Rule.PassThreshold {
		apiErr := newError(409, "INSUFFICIENT_POOL",
			fmt.Sprintf("题池不足：已选 %d 题，最高加权分 %.1f，低于门槛 %.1f", len(selected), score, req.Rule.PassThreshold))
		apiErr.Warnings = warnings
		return result, apiErr
	}
	return result, nil
}

func (s *Service) fillSubject(
	ctx context.Context,
	childID, subject string,
	stages []string,
	primaryRank, target, need int,
	rng *rand.Rand,
	chosen map[string]bool,
	selected *[]Selected,
	addWarning func(string),
) error {
	if need <= 0 {
		return nil
	}

	fresh, err := s.repo.pool(ctx, childID, subject, stages, true, defaultPoolLimit)
	if err != nil {
		return err
	}
	sortCandidates(fresh, rng, primaryRank, target)

	picked := 0
	for _, candidate := range fresh {
		if picked >= need {
			break
		}
		if chosen[candidate.ID] {
			continue
		}
		*selected = append(*selected, toSelected(candidate, false))
		chosen[candidate.ID] = true
		picked++
		if primaryRank >= 0 && stageRanks[candidate.Stage] != primaryRank {
			addWarning("stage_fallback:" + subject)
		}
		if candidate.Difficulty != target {
			addWarning("difficulty_fallback:" + subject)
		}
	}

	if picked >= need || childID == "" {
		if picked < need {
			addWarning("subject_shortage:" + subject)
		}
		return nil
	}

	// 去重导致不足时，退化为允许重复题。
	all, err := s.repo.pool(ctx, childID, subject, stages, false, defaultPoolLimit)
	if err != nil {
		return err
	}
	sortCandidates(all, rng, primaryRank, target)
	for _, candidate := range all {
		if picked >= need {
			break
		}
		if chosen[candidate.ID] {
			continue
		}
		*selected = append(*selected, toSelected(candidate, true))
		chosen[candidate.ID] = true
		picked++
		addWarning("repeat_question:" + subject)
	}
	if picked < need {
		addWarning("subject_shortage:" + subject)
	}
	return nil
}

func toSelected(c Candidate, repeated bool) Selected {
	return Selected{
		QuestionID: c.ID,
		Subject:    c.Subject,
		Stage:      c.Stage,
		Type:       c.Type,
		Difficulty: c.Difficulty,
		Repeated:   repeated,
	}
}

func sortCandidates(items []Candidate, rng *rand.Rand, primaryRank, target int) {
	rng.Shuffle(len(items), func(i, j int) {
		items[i], items[j] = items[j], items[i]
	})
	sort.SliceStable(items, func(i, j int) bool {
		ri, rj := stageRanks[items[i].Stage], stageRanks[items[j].Stage]
		if primaryRank >= 0 {
			di, dj := abs(ri-primaryRank), abs(rj-primaryRank)
			if di != dj {
				return di < dj
			}
		}
		di, dj := abs(items[i].Difficulty-target), abs(items[j].Difficulty-target)
		if di != dj {
			return di < dj
		}
		return false
	})
}

func validateRule(rule Rule) error {
	if rule.PassThreshold <= 0 {
		return newError(422, "VALIDATION_ERROR", "加权门槛必须大于 0")
	}
	if len(rule.SubjectWeight) == 0 {
		return newError(422, "VALIDATION_ERROR", "学科权重不能为空")
	}
	minSubjectWeight := math.MaxFloat64
	hasSubject := false
	for subject, weight := range rule.SubjectWeight {
		if weight < 0 {
			return newError(422, "VALIDATION_ERROR", "学科权重不能为负")
		}
		if subject == "fun" {
			continue
		}
		if weight > 0 {
			hasSubject = true
			if weight < minSubjectWeight {
				minSubjectWeight = weight
			}
		}
	}
	if !hasSubject {
		return newError(422, "VALIDATION_ERROR", "至少需要一个非趣味学科权重")
	}
	if funWeight := rule.SubjectWeight["fun"]; funWeight > 0 && funWeight >= minSubjectWeight {
		return newError(422, "VALIDATION_ERROR", "趣味题权重必须低于最低学科权重")
	}
	if rule.FunRatioCap < 0 || rule.FunRatioCap > 10 {
		return newError(422, "VALIDATION_ERROR", "趣味题上限需在 0–10 之间")
	}
	return nil
}

func sessionSize(rule Rule, maxQuestions int) (int, error) {
	maxWeight := 0.0
	for subject, weight := range rule.SubjectWeight {
		if subject == "fun" {
			continue
		}
		if weight > maxWeight {
			maxWeight = weight
		}
	}
	if maxWeight <= 0 {
		return 0, newError(422, "VALIDATION_ERROR", "至少需要一个非趣味学科权重")
	}
	nMin := int(math.Ceil(rule.PassThreshold / maxWeight))
	if nMin < 3 {
		nMin = 3
	}
	n := nMin + 2
	if n > maxQuestions {
		n = maxQuestions
	}
	if n < 3 {
		n = 3
	}
	return n, nil
}

// allocate 使用最大余数法分配题量。
func allocate(weights map[string]float64, total int) map[string]int {
	quota := map[string]int{}
	if total <= 0 {
		return quota
	}
	subjects := subjectsByWeight(weights)
	sum := 0.0
	for _, subject := range subjects {
		sum += weights[subject]
	}
	type remainder struct {
		subject string
		value   float64
	}
	remainders := make([]remainder, 0, len(subjects))
	allocated := 0
	for _, subject := range subjects {
		exact := float64(total) * weights[subject] / sum
		base := int(math.Floor(exact))
		quota[subject] = base
		allocated += base
		remainders = append(remainders, remainder{subject, exact - float64(base)})
	}
	sort.SliceStable(remainders, func(i, j int) bool {
		if remainders[i].value != remainders[j].value {
			return remainders[i].value > remainders[j].value
		}
		return weights[remainders[i].subject] > weights[remainders[j].subject]
	})
	for i := 0; allocated < total; i++ {
		quota[remainders[i%len(remainders)].subject]++
		allocated++
	}
	return quota
}

func subjectsByWeight(weights map[string]float64) []string {
	subjects := make([]string, 0, len(weights))
	for subject, weight := range weights {
		if weight > 0 {
			subjects = append(subjects, subject)
		}
	}
	sort.Slice(subjects, func(i, j int) bool {
		if weights[subjects[i]] != weights[subjects[j]] {
			return weights[subjects[i]] > weights[subjects[j]]
		}
		return subjects[i] < subjects[j]
	})
	return subjects
}

func targetDifficulty(stage, grade string, stats map[int]float64) int {
	best, bestDistance := 0, math.MaxFloat64
	for difficulty, rate := range stats {
		distance := math.Abs(rate - 0.7)
		if distance < bestDistance {
			best, bestDistance = difficulty, distance
		}
	}
	if best > 0 && bestDistance <= 0.25 {
		return best
	}

	base := map[string]int{"preschool": 1, "low": 2, "mid": 3, "high": 3}[stage]
	if len(grade) == 2 && grade[0] == 'g' {
		switch grade[1] {
		case '1', '2', '3':
			base--
		case '7', '8', '9':
			base++
		}
	}
	return clamp(base, 1, 5)
}

func abs(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

func clamp(value, low, high int) int {
	if value < low {
		return low
	}
	if value > high {
		return high
	}
	return value
}

func round2(value float64) float64 {
	return math.Round(value*100) / 100
}

