package rule

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

const ruleColumns = `
	unlock_minutes, pass_threshold, subject_weight::text, fun_ratio_cap, fun_enabled,
	weight_preset, time_window::text, daily_limit, offline_fallback_min, scope_mode,
	allowed_apps::text, timezone, version`

type repository struct {
	pool *pgxpool.Pool
}

func newRepository(pool *pgxpool.Pool) *repository {
	return &repository{pool: pool}
}

func scanRule(row pgx.Row) (Rule, int, error) {
	var r Rule
	var version int
	var weights, timeWindow, apps string
	if err := row.Scan(
		&r.UnlockMinutes, &r.PassThreshold, &weights, &r.FunRatioCap, &r.FunEnabled,
		&r.WeightPreset, &timeWindow, &r.DailyLimit, &r.OfflineFallbackMin, &r.ScopeMode,
		&apps, &r.Timezone, &version); err != nil {
		return Rule{}, 0, err
	}
	r.SubjectWeight = map[string]float64{}
	if err := json.Unmarshal([]byte(weights), &r.SubjectWeight); err != nil {
		return Rule{}, 0, fmt.Errorf("decode subject_weight: %w", err)
	}
	if err := json.Unmarshal([]byte(timeWindow), &r.TimeWindow); err != nil {
		return Rule{}, 0, fmt.Errorf("decode time_window: %w", err)
	}
	if err := json.Unmarshal([]byte(apps), &r.AllowedApps); err != nil {
		return Rule{}, 0, fmt.Errorf("decode allowed_apps: %w", err)
	}
	return r, version, nil
}

func (r *repository) getForChild(ctx context.Context, childID string) (Rule, int, error) {
	return scanRule(r.pool.QueryRow(ctx,
		`select `+ruleColumns+` from watch_rule where child_id = $1`, childID))
}

func (r *repository) getForParent(ctx context.Context, accountID, childID string) (Rule, int, error) {
	return scanRule(r.pool.QueryRow(ctx, `
		select `+ruleColumns+`
		from watch_rule wr
		where wr.child_id = $1
		  and exists (
		      select 1 from child_profile c
		      join family_member fm on fm.family_id = c.family_id
		      where c.id = wr.child_id and fm.account_id = $2
		  )`, childID, accountID))
}

func (r *repository) update(ctx context.Context, accountID, childID string, in Rule) (int, error) {
	weights, _ := json.Marshal(in.SubjectWeight)
	timeWindow, _ := json.Marshal(in.TimeWindow)
	apps, _ := json.Marshal(in.AllowedApps)

	var version int
	err := r.pool.QueryRow(ctx, `
		update watch_rule wr
		set unlock_minutes = $3,
		    pass_threshold = $4,
		    subject_weight = $5::jsonb,
		    fun_ratio_cap = $6,
		    fun_enabled = $7,
		    weight_preset = $8,
		    time_window = $9::jsonb,
		    daily_limit = $10,
		    offline_fallback_min = $11,
		    scope_mode = $12,
		    allowed_apps = $13::jsonb,
		    timezone = $14,
		    version = version + 1,
		    updated_by = $2,
		    updated_at = now()
		where wr.child_id = $1
		  and exists (
		      select 1 from child_profile c
		      join family_member fm on fm.family_id = c.family_id
		      where c.id = wr.child_id and fm.account_id = $2
		  )
		returning version`,
		childID, accountID,
		in.UnlockMinutes, in.PassThreshold, string(weights), in.FunRatioCap, in.FunEnabled,
		in.WeightPreset, string(timeWindow), in.DailyLimit, in.OfflineFallbackMin,
		in.ScopeMode, string(apps), in.Timezone).Scan(&version)
	return version, err
}

func (r *repository) usageSeconds(ctx context.Context, childID string, start, end time.Time) (used, reserved int, err error) {
	if err = r.pool.QueryRow(ctx, `
		select coalesce(sum(watched_seconds), 0)::int
		from watch_log
		where child_id = $1 and start_at >= $2 and start_at < $3`,
		childID, start, end).Scan(&used); err != nil {
		return 0, 0, err
	}
	if err = r.pool.QueryRow(ctx, `
		select coalesce(sum(minutes * 60 - consumed_seconds), 0)::int
		from watch_grant
		where child_id = $1 and status = 'active' and valid_until > now()`,
		childID).Scan(&reserved); err != nil {
		return 0, 0, err
	}
	return used, reserved, nil
}

func (r *repository) validSubjects(ctx context.Context) (map[string]bool, error) {
	rows, err := r.pool.Query(ctx, `
		select code from tag_dict where tag_type = 'subject' and enabled = true`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	subjects := map[string]bool{}
	for rows.Next() {
		var code string
		if err := rows.Scan(&code); err != nil {
			return nil, err
		}
		subjects[code] = true
	}
	return subjects, rows.Err()
}

func (r *repository) audit(ctx context.Context, accountID, childID string, before, after Rule, ip string) error {
	encode := func(value Rule) string {
		payload, _ := json.Marshal(value)
		return string(payload)
	}
	_, err := r.pool.Exec(ctx, `
		insert into audit_log (actor_type, actor_id, action, target_type, target_id,
		                       before_data, after_data, ip)
		values ('parent', $1, 'rule.update', 'child', $2, $3::jsonb, $4::jsonb, nullif($5, '')::inet)`,
		accountID, childID, encode(before), encode(after), ip)
	return err
}

func isNoRows(err error) bool {
	return errors.Is(err, pgx.ErrNoRows)
}

package rule

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/roma007/OpenQuizGo/internal/identity"
)

// Error 是规则业务错误。
type Error struct {
	Status  int
	Code    string
	Message string
}

func (e *Error) Error() string { return e.Message }

func newError(status int, code, message string) *Error {
	return &Error{Status: status, Code: code, Message: message}
}

// PreviewResult 是规则 dry-run 结果。
type PreviewResult struct {
	N         int            `json:"n"`
	Quota     map[string]int `json:"quota"`
	FunSlots  int            `json:"fun_slots"`
	MaxScore  float64        `json:"max_score"`
	Warnings  []string       `json:"warnings,omitempty"`
}

// ContextResult 是电视端可看状态。
type ContextResult struct {
	Allowed          bool      `json:"allowed"`
	Reason           string    `json:"reason"`
	Rule             Rule      `json:"rule"`
	RuleVersion      int       `json:"rule_version"`
	DailyLimit       int       `json:"daily_limit"`
	UsedMinutes      int       `json:"used_minutes"`
	ReservedMinutes  int       `json:"reserved_minutes"`
	RemainingMinutes int       `json:"remaining_minutes"`
	Now              time.Time `json:"now"`
}

// Service 提供规则读取、更新、dry-run 与判定。
type Service struct {
	repo     *repository
	identity *identity.Service
	logger   *slog.Logger
}

// New 构造规则服务。
func New(pool *pgxpool.Pool, identityService *identity.Service, logger *slog.Logger) *Service {
	return &Service{repo: newRepository(pool), identity: identityService, logger: logger}
}

// Get 返回孩子规则。
func (s *Service) Get(ctx context.Context, accountID, childID string) (Rule, int, error) {
	r, version, err := s.repo.getForParent(ctx, accountID, childID)
	if isNoRows(err) {
		return Rule{}, 0, newError(404, "RULE_NOT_FOUND", "规则不存在")
	}
	return r, version, err
}

// Update 更新规则（需家长 PIN）。
func (s *Service) Update(ctx context.Context, accountID, childID, pin string, in Rule, ip string) (Rule, int, error) {
	in = Normalize(in)
	if err := s.validate(ctx, in); err != nil {
		return Rule{}, 0, err
	}
	if err := s.verifyPIN(ctx, accountID, pin); err != nil {
		return Rule{}, 0, err
	}
	before, _, err := s.repo.getForParent(ctx, accountID, childID)
	if isNoRows(err) {
		return Rule{}, 0, newError(404, "RULE_NOT_FOUND", "规则不存在")
	}
	if err != nil {
		return Rule{}, 0, err
	}
	version, err := s.repo.update(ctx, accountID, childID, in)
	if isNoRows(err) {
		return Rule{}, 0, newError(404, "RULE_NOT_FOUND", "规则不存在")
	}
	if err != nil {
		return Rule{}, 0, err
	}
	if err := s.repo.audit(ctx, accountID, childID, before, in, ip); err != nil {
		s.logger.Error("audit rule update", "error", err, "child_id", childID)
	}
	return in, version, nil
}

// Preview 校验规则并给出会话题量预估。
func (s *Service) Preview(ctx context.Context, accountID, childID string, in Rule) (PreviewResult, error) {
	in = Normalize(in)
	if _, _, err := s.repo.getForParent(ctx, accountID, childID); err != nil {
		if isNoRows(err) {
			return PreviewResult{}, newError(404, "RULE_NOT_FOUND", "规则不存在")
		}
		return PreviewResult{}, err
	}
	if err := s.validate(ctx, in); err != nil {
		return PreviewResult{}, err
	}
	n, _ := SessionSize(in)
	funSlots := 0
	if in.FunEnabled && in.FunRatioCap > 0 && in.SubjectWeight["fun"] > 0 {
		funSlots = min(in.FunRatioCap, max(1, n-1))
	}
	weights := make(map[string]float64)
	for subject, weight := range in.SubjectWeight {
		if subject != "fun" && weight > 0 {
			weights[subject] = weight
		}
	}
	quota := Allocate(weights, n-funSlots)
	maxScore := float64(funSlots) * in.SubjectWeight["fun"]
	for subject, count := range quota {
		maxScore += float64(count) * in.SubjectWeight[subject]
	}
	result := PreviewResult{N: n, Quota: quota, FunSlots: funSlots, MaxScore: maxScore}
	if in.PassThreshold > maxScore*0.9 {
		result.Warnings = append(result.Warnings, "门槛接近可达上限，孩子可能需要全部答对")
	}
	return result, nil
}

// Context 返回电视端当前可看状态。
func (s *Service) Context(ctx context.Context, childID string) (ContextResult, error) {
	r, version, err := s.repo.getForChild(ctx, childID)
	if isNoRows(err) {
		return ContextResult{}, newError(404, "RULE_NOT_FOUND", "规则不存在")
	}
	if err != nil {
		return ContextResult{}, err
	}
	now := time.Now()
	allowedByTime, err := AllowedAt(r, now)
	if err != nil {
		return ContextResult{}, err
	}
	start, end, err := DayBounds(r, now)
	if err != nil {
		return ContextResult{}, err
	}
	used, reserved, err := s.repo.usageSeconds(ctx, childID, start, end)
	if err != nil {
		return ContextResult{}, err
	}
	remaining := r.DailyLimit - ceilMinutes(used+reserved)

	result := ContextResult{
		Allowed:          allowedByTime && remaining > 0,
		Reason:           "ok",
		Rule:             r,
		RuleVersion:      version,
		DailyLimit:       r.DailyLimit,
		UsedMinutes:      ceilMinutes(used),
		ReservedMinutes:  ceilMinutes(reserved),
		RemainingMinutes: max(0, remaining),
		Now:              now,
	}
	if !allowedByTime {
		result.Reason = "time_window"
	} else if remaining <= 0 {
		result.Reason = "daily_limit"
	}
	return result, nil
}

// CanStart 在创建答题会话前执行时段与额度校验。
func (s *Service) CanStart(ctx context.Context, childID string) (Rule, int, error) {
	r, version, err := s.repo.getForChild(ctx, childID)
	if isNoRows(err) {
		return Rule{}, 0, newError(404, "RULE_NOT_FOUND", "规则不存在")
	}
	if err != nil {
		return Rule{}, 0, err
	}
	now := time.Now()
	allowed, err := AllowedAt(r, now)
	if err != nil {
		return Rule{}, 0, err
	}
	if !allowed {
		return Rule{}, 0, newError(403, "RULE_TIME_WINDOW", "当前不在允许观看时段")
	}
	start, end, err := DayBounds(r, now)
	if err != nil {
		return Rule{}, 0, err
	}
	used, reserved, err := s.repo.usageSeconds(ctx, childID, start, end)
	if err != nil {
		return Rule{}, 0, err
	}
	if r.DailyLimit-ceilMinutes(used+reserved) <= 0 {
		return Rule{}, 0, newError(403, "RULE_DAILY_LIMIT", "今日观看额度已用完")
	}
	return r, version, nil
}

func (s *Service) validate(ctx context.Context, in Rule) error {
	if err := Validate(in); err != nil {
		return newError(422, "VALIDATION_ERROR", err.Error())
	}
	subjects, err := s.repo.validSubjects(ctx)
	if err != nil {
		return err
	}
	for subject := range in.SubjectWeight {
		if !subjects[subject] {
			return newError(422, "VALIDATION_ERROR", fmt.Sprintf("学科不存在或已禁用：%s", subject))
		}
	}
	return nil
}

func (s *Service) verifyPIN(ctx context.Context, accountID, pin string) error {
	if s.identity == nil {
		return nil
	}
	if err := s.identity.VerifyPIN(ctx, accountID, pin); err != nil {
		var identityErr *identity.Error
		if errors.As(err, &identityErr) {
			if identityErr.Code == "PIN_NOT_SET" {
				return newError(403, "PIN_REQUIRED", "请先设置家长 PIN")
			}
			if identityErr.Code == "PIN_INVALID" {
				return newError(403, "PIN_INVALID", "家长 PIN 不正确")
			}
		}
		return err
	}
	return nil
}

func ceilMinutes(seconds int) int {
	if seconds <= 0 {
		return 0
	}
	return (seconds + 59) / 60
}

package rule

import (
	"encoding/json"
	"errors"
	"net/http"

	"github.com/go-chi/chi/v5"

	"github.com/roma007/OpenQuizGo/internal/identity"
)

// ParentRoutes 注册家长端规则接口（需家长令牌）。
func (s *Service) ParentRoutes(r chi.Router) {
	r.Get("/family/children/{childID}/rule", s.handleGet)
	r.Put("/family/children/{childID}/rule", s.handleUpdate)
	r.Post("/family/children/{childID}/rule/preview", s.handlePreview)
}

// DeviceRoutes 注册电视端上下文接口（需设备令牌）。
func (s *Service) DeviceRoutes(r chi.Router) {
	r.Get("/child/context", s.handleContext)
}

func (s *Service) handleGet(w http.ResponseWriter, r *http.Request) {
	rule, version, err := s.Get(r.Context(), identity.AccountIDFrom(r.Context()), chi.URLParam(r, "childID"))
	if err != nil {
		writeRuleError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"rule": rule, "version": version})
}

func (s *Service) handleUpdate(w http.ResponseWriter, r *http.Request) {
	var req struct {
		PIN  string `json:"pin"`
		Rule Rule   `json:"rule"`
	}
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeRuleError(w, r, newError(422, "VALIDATION_ERROR", "请求体不是合法 JSON"))
		return
	}
	updated, version, err := s.Update(r.Context(), identity.AccountIDFrom(r.Context()),
		chi.URLParam(r, "childID"), req.PIN, req.Rule, clientIP(r))
	if err != nil {
		writeRuleError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"rule": updated, "version": version})
}

func (s *Service) handlePreview(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Rule Rule `json:"rule"`
	}
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeRuleError(w, r, newError(422, "VALIDATION_ERROR", "请求体不是合法 JSON"))
		return
	}
	result, err := s.Preview(r.Context(), identity.AccountIDFrom(r.Context()),
		chi.URLParam(r, "childID"), req.Rule)
	if err != nil {
		writeRuleError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, result)
}

func (s *Service) handleContext(w http.ResponseWriter, r *http.Request) {
	principal, ok := identity.DeviceFrom(r.Context())
	if !ok {
		writeRuleError(w, r, newError(401, "AUTH_INVALID_TOKEN", "设备未授权"))
		return
	}
	result, err := s.Context(r.Context(), principal.ChildID)
	if err != nil {
		writeRuleError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, result)
}

func writeRuleError(w http.ResponseWriter, r *http.Request, err error) {
	var ruleErr *Error
	if errors.As(err, &ruleErr) {
		writeJSON(w, ruleErr.Status, map[string]string{
			"code":       ruleErr.Code,
			"message":    ruleErr.Message,
			"request_id": w.Header().Get("X-Request-Id"),
		})
		return
	}
	writeJSON(w, http.StatusInternalServerError, map[string]string{
		"code":       "INTERNAL",
		"message":    "服务端错误",
		"request_id": w.Header().Get("X-Request-Id"),
	})
}

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

func clientIP(r *http.Request) string {
	host := r.RemoteAddr
	for i := len(host) - 1; i >= 0; i-- {
		if host[i] == ':' {
			if i > 0 && host[0] == '[' {
				return host[1 : i-1]
			}
			return host[:i]
		}
	}
	return host
}

