package watch

import "time"

// Grant 是服务端签发的观看授权。
type Grant struct {
	GrantID         string    `json:"grant_id"`
	SessionID       string    `json:"session_id"`
	Minutes         int       `json:"minutes"`
	ValidFrom       time.Time `json:"valid_from"`
	ValidUntil      time.Time `json:"valid_until"`
	RemainingSeconds int      `json:"remaining_seconds"`
	Status          string    `json:"status"`
	LeaseToken      string    `json:"lease_token,omitempty"`
}

// IssueRequest 是签发授权的入参。
type IssueRequest struct {
	SessionID string
	ChildID   string
	DeviceID  string
	Rule      RuleView
}

// RuleView 是计量所需的规则字段（避免 watch 直接依赖 quiz）。
type RuleView struct {
	UnlockMinutes int
	DailyLimit    int
	Timezone      string
}

// HeartbeatRequest 是心跳入参。
type HeartbeatRequest struct {
	ForegroundApp string `json:"foreground_app"`
	Paused        bool   `json:"paused"`
	PositionSec   int    `json:"position_seconds"`
}

// HeartbeatResult 是心跳结果。
type HeartbeatResult struct {
	GrantID          string    `json:"grant_id"`
	Status           string    `json:"status"`
	ConsumedSeconds  int       `json:"consumed_seconds"`
	RemainingSeconds int       `json:"remaining_seconds"`
	Paused           bool      `json:"paused"`
	Revoked          bool      `json:"revoked"`
	Reason           string    `json:"reason,omitempty"`
	ServerTime       time.Time `json:"server_time"`
}

// Error 是计量业务错误。
type Error struct {
	Status  int
	Code    string
	Message string
}

func (e *Error) Error() string { return e.Message }

func newError(status int, code, message string) *Error {
	return &Error{Status: status, Code: code, Message: message}
}

// Capability 是设备能力上报。
type Capability struct {
	GuardMode   string          `json:"guard_mode"`
	Permissions map[string]bool `json:"permissions"`
	OSVersion   string          `json:"os_version"`
	AppVersion  string          `json:"app_version"`
}

// TamperEvent 是篡改/权限异常上报。
type TamperEvent struct {
	Type   string          `json:"type"`
	Detail map[string]any  `json:"detail"`
}

package watch

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

const grantColumns = `
	id, session_id, child_id, device_id, minutes, valid_from, valid_until,
	jti, consumed_seconds, status, last_heartbeat_at, created_at`

type grantRecord struct {
	ID               string
	SessionID        string
	ChildID          string
	DeviceID         string
	Minutes          int
	ValidFrom        time.Time
	ValidUntil       time.Time
	JTI              string
	ConsumedSeconds  int
	Status           string
	LastHeartbeatAt  time.Time
	CreatedAt        time.Time
}

func scanGrant(row pgx.Row) (grantRecord, error) {
	var g grantRecord
	err := row.Scan(&g.ID, &g.SessionID, &g.ChildID, &g.DeviceID, &g.Minutes,
		&g.ValidFrom, &g.ValidUntil, &g.JTI, &g.ConsumedSeconds, &g.Status,
		&g.LastHeartbeatAt, &g.CreatedAt)
	return g, err
}

type repository struct {
	pool *pgxpool.Pool
}

func newRepository(pool *pgxpool.Pool) *repository {
	return &repository{pool: pool}
}

// issue 在事务内串行化同一孩子的授权签发，避免并发超发。
func (r *repository) issue(ctx context.Context, req IssueRequest, start, end time.Time,
	jti string, now time.Time) (grantRecord, bool, error) {
	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return grantRecord{}, false, fmt.Errorf("begin: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	if _, err := tx.Exec(ctx, `select pg_advisory_xact_lock(hashtext($1))`, req.ChildID); err != nil {
		return grantRecord{}, false, fmt.Errorf("lock child: %w", err)
	}

	existing, err := scanGrant(tx.QueryRow(ctx,
		`select `+grantColumns+` from watch_grant where session_id = $1`, req.SessionID))
	if err == nil {
		if err := tx.Commit(ctx); err != nil {
			return grantRecord{}, false, err
		}
		return existing, false, nil
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		return grantRecord{}, false, err
	}

	var used, reserved int
	if err := tx.QueryRow(ctx, `
		select coalesce(sum(watched_seconds), 0)::int
		from watch_log where child_id = $1 and start_at >= $2 and start_at < $3`,
		req.ChildID, start, end).Scan(&used); err != nil {
		return grantRecord{}, false, err
	}
	if err := tx.QueryRow(ctx, `
		select coalesce(sum(minutes * 60 - consumed_seconds), 0)::int
		from watch_grant
		where child_id = $1 and status = 'active' and valid_until > $2`,
		req.ChildID, now).Scan(&reserved); err != nil {
		return grantRecord{}, false, err
	}

	dailySeconds := req.Rule.DailyLimit * 60
	if req.Rule.DailyLimit <= 0 {
		dailySeconds = 60 * 60
	}
	available := dailySeconds - used - reserved
	minutes := req.Rule.UnlockMinutes
	if minutes <= 0 {
		minutes = 20
	}
	if availMinutes := available / 60; availMinutes < minutes {
		minutes = availMinutes
	}
	if minutes < 1 {
		return grantRecord{}, false, newError(403, "RULE_DAILY_LIMIT", "今日观看额度已用完")
	}

	validUntil := now.Add(time.Duration(minutes) * time.Minute)
	rec, err := scanGrant(tx.QueryRow(ctx, `
		insert into watch_grant (
			child_id, device_id, session_id, minutes, valid_from, valid_until, jti,
			consumed_seconds, status, last_heartbeat_at)
		values ($1, $2, $3, $4, $5, $6, $7, 0, 'active', $5)
		returning `+grantColumns,
		req.ChildID, req.DeviceID, req.SessionID, minutes, now, validUntil, jti))
	if err != nil {
		return grantRecord{}, false, fmt.Errorf("insert grant: %w", err)
	}
	if err := tx.Commit(ctx); err != nil {
		return grantRecord{}, false, err
	}
	return rec, true, nil
}

func (r *repository) grantBySession(ctx context.Context, sessionID string) (grantRecord, error) {
	return scanGrant(r.pool.QueryRow(ctx,
		`select `+grantColumns+` from watch_grant where session_id = $1`, sessionID))
}

func (r *repository) activeGrant(ctx context.Context, deviceID, childID string, now time.Time) (grantRecord, error) {
	return scanGrant(r.pool.QueryRow(ctx, `
		select `+grantColumns+` from watch_grant
		where device_id = $1 and child_id = $2 and status = 'active' and valid_until > $3
		order by created_at desc limit 1`, deviceID, childID, now))
}

type heartbeatOutcome struct {
	Grant       grantRecord
	WatchedSec  int
	PausedSec   int
	Revoked     bool
	Reason      string
}

func (r *repository) heartbeat(ctx context.Context, grantID, deviceID, childID string,
	allowedByTime bool, clientPaused bool, now time.Time) (heartbeatOutcome, error) {
	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return heartbeatOutcome{}, fmt.Errorf("begin: %w", err)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	rec, err := scanGrant(tx.QueryRow(ctx, `
		select `+grantColumns+` from watch_grant
		where id = $1 and device_id = $2 and child_id = $3
		for update`, grantID, deviceID, childID))
	if err != nil {
		return heartbeatOutcome{}, err
	}

	outcome := heartbeatOutcome{Grant: rec}
	if rec.Status != "active" {
		return outcome, tx.Commit(ctx)
	}
	if now.After(rec.ValidUntil) {
		if _, err := tx.Exec(ctx, `update watch_grant set status = 'expired' where id = $1`, rec.ID); err != nil {
			return outcome, err
		}
		rec.Status = "expired"
		outcome.Grant = rec
		outcome.Reason = "expired"
		return outcome, tx.Commit(ctx)
	}
	if !allowedByTime {
		if _, err := tx.Exec(ctx, `update watch_grant set status = 'revoked' where id = $1`, rec.ID); err != nil {
			return outcome, err
		}
		rec.Status = "revoked"
		outcome.Grant = rec
		outcome.Revoked = true
		outcome.Reason = "time_window"
		return outcome, tx.Commit(ctx)
	}

	quizActive := false
	if err := tx.QueryRow(ctx, `
		select exists (
			select 1 from quiz_session
			where device_id = $1 and child_id = $2 and state = 'active'
		)`, deviceID, childID).Scan(&quizActive); err != nil {
		return outcome, err
	}

	delta := int(now.Sub(rec.LastHeartbeatAt).Seconds())
	if delta < 0 {
		delta = 0
	}
	if delta > 120 {
		delta = 120
	}
	paused := clientPaused || quizActive
	watched := 0
	pausedSec := 0
	if paused {
		pausedSec = delta
	} else {
		watched = delta
	}
	remaining := rec.Minutes*60 - rec.ConsumedSeconds
	if watched > remaining {
		watched = remaining
	}
	consumed := rec.ConsumedSeconds + watched
	status := rec.Status
	if consumed >= rec.Minutes*60 {
		status = "exhausted"
	}

	if _, err := tx.Exec(ctx, `
		update watch_grant
		set consumed_seconds = $2, status = $3, last_heartbeat_at = $4
		where id = $1`, rec.ID, consumed, status, now); err != nil {
		return outcome, err
	}

	if delta > 0 {
		if _, err := tx.Exec(ctx, `
			insert into watch_log (grant_id, child_id, device_id, target_type, target_id,
			                       start_at, end_at, watched_seconds, paused_seconds)
			values ($1, $2, $3, 'app', $4, $5, $6, $7, $8)`,
			rec.ID, childID, deviceID, "", rec.LastHeartbeatAt, now, watched, pausedSec); err != nil {
			return outcome, err
		}
	}

	rec.ConsumedSeconds = consumed
	rec.Status = status
	rec.LastHeartbeatAt = now
	outcome.Grant = rec
	outcome.WatchedSec = watched
	outcome.PausedSec = pausedSec
	return outcome, tx.Commit(ctx)
}

func (r *repository) upsertCapability(ctx context.Context, deviceID string, c Capability) error {
	permissions, _ := json.Marshal(c.Permissions)
	_, err := r.pool.Exec(ctx, `
		insert into device_capability (device_id, guard_mode, permissions, os_version, app_version, last_reported_at)
		values ($1, $2, $3::jsonb, $4, $5, now())
		on conflict (device_id) do update set
			guard_mode = excluded.guard_mode,
			permissions = excluded.permissions,
			os_version = excluded.os_version,
			app_version = excluded.app_version,
			last_reported_at = now()`,
		deviceID, c.GuardMode, string(permissions), c.OSVersion, c.AppVersion)
	return err
}

func (r *repository) insertTamper(ctx context.Context, deviceID, childID string, event TamperEvent) error {
	detail, _ := json.Marshal(event.Detail)
	_, err := r.pool.Exec(ctx, `
		insert into tamper_event (device_id, child_id, type, detail)
		values ($1, $2, $3, $4::jsonb)`, deviceID, childID, event.Type, string(detail))
	return err
}

package watch

import (
	"context"
	"crypto/rand"
	"encoding/base64"
	"errors"
	"log/slog"
	"time"

	"github.com/golang-jwt/jwt/v5"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/roma007/OpenQuizGo/internal/identity"
	"github.com/roma007/OpenQuizGo/internal/rule"
)

var validTamperTypes = map[string]bool{
	"permission_revoked": true,
	"uninstall_attempt":  true,
	"package_tampered":   true,
	"clock_skew":         true,
	"other":              true,
}

// Service 负责授权签发、心跳计量与设备异常上报。
type Service struct {
	repo    *repository
	ruleSvc *rule.Service
	secret  []byte
	logger  *slog.Logger
}

// New 构造计量服务。
func New(pool *pgxpool.Pool, ruleSvc *rule.Service, secret string, logger *slog.Logger) *Service {
	return &Service{repo: newRepository(pool), ruleSvc: ruleSvc, secret: []byte(secret), logger: logger}
}

// Issue 为通过的答题会话签发授权（同一会话幂等）。
func (s *Service) Issue(ctx context.Context, req IssueRequest) (Grant, error) {
	if req.SessionID == "" || req.ChildID == "" || req.DeviceID == "" {
		return Grant{}, newError(422, "VALIDATION_ERROR", "缺少会话、孩子或设备")
	}
	now := time.Now()
	location := time.UTC
	if req.Rule.Timezone != "" {
		if loc, err := time.LoadLocation(req.Rule.Timezone); err == nil {
			location = loc
		}
	}
	local := now.In(location)
	start := time.Date(local.Year(), local.Month(), local.Day(), 0, 0, 0, 0, location)
	end := start.Add(24 * time.Hour)

	jti := randomToken()
	rec, _, err := s.repo.issue(ctx, req, start, end, jti, now)
	if err != nil {
		return Grant{}, err
	}
	return s.toGrant(rec), nil
}

// GrantForSession 返回会话已签发的授权。
func (s *Service) GrantForSession(ctx context.Context, sessionID string) (Grant, error) {
	rec, err := s.repo.grantBySession(ctx, sessionID)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return Grant{}, newError(404, "GRANT_NOT_FOUND", "授权不存在")
		}
		return Grant{}, err
	}
	return s.toGrant(rec), nil
}

// ActiveGrant 返回设备当前有效授权。
func (s *Service) ActiveGrant(ctx context.Context, principal identity.DevicePrincipal) (Grant, error) {
	rec, err := s.repo.activeGrant(ctx, principal.DeviceID, principal.ChildID, time.Now())
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return Grant{}, newError(404, "GRANT_NOT_FOUND", "当前没有有效授权")
		}
		return Grant{}, err
	}
	return s.toGrant(rec), nil
}

// Heartbeat 计费心跳：答题期间与客户端暂停时不计入观看时长。
func (s *Service) Heartbeat(ctx context.Context, principal identity.DevicePrincipal,
	grantID string, req HeartbeatRequest) (HeartbeatResult, error) {
	now := time.Now()
	allowed := true
	if s.ruleSvc != nil {
		r, _, err := s.ruleSvc.GetForChild(ctx, principal.ChildID)
		if err == nil {
			allowed, _ = rule.AllowedAt(r, now)
		} else {
			var ruleErr *rule.Error
			if !errors.As(err, &ruleErr) || ruleErr.Code != "RULE_NOT_FOUND" {
				return HeartbeatResult{}, err
			}
		}
	}

	outcome, err := s.repo.heartbeat(ctx, grantID, principal.DeviceID, principal.ChildID,
		allowed, req.Paused, now)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return HeartbeatResult{}, newError(404, "GRANT_NOT_FOUND", "授权不存在")
		}
		return HeartbeatResult{}, err
	}
	remaining := outcome.Grant.Minutes*60 - outcome.Grant.ConsumedSeconds
	if remaining < 0 {
		remaining = 0
	}
	result := HeartbeatResult{
		GrantID:          outcome.Grant.ID,
		Status:           outcome.Grant.Status,
		ConsumedSeconds:  outcome.Grant.ConsumedSeconds,
		RemainingSeconds: remaining,
		Paused:           req.Paused || outcome.PausedSec > 0,
		Revoked:          outcome.Revoked || outcome.Grant.Status == "revoked",
		Reason:           outcome.Reason,
		ServerTime:       now,
	}
	return result, nil
}

// ReportCapability 记录设备防护模式与权限状态。
func (s *Service) ReportCapability(ctx context.Context, principal identity.DevicePrincipal, c Capability) error {
	if c.GuardMode == "" {
		c.GuardMode = "standard"
	}
	if c.GuardMode != "standard" && c.GuardMode != "device_owner" {
		return newError(422, "VALIDATION_ERROR", "guard_mode 不合法")
	}
	return s.repo.upsertCapability(ctx, principal.DeviceID, c)
}

// ReportTamper 记录权限关闭、卸载尝试等异常。
func (s *Service) ReportTamper(ctx context.Context, principal identity.DevicePrincipal, event TamperEvent) error {
	if !validTamperTypes[event.Type] {
		return newError(422, "VALIDATION_ERROR", "异常类型不合法")
	}
	return s.repo.insertTamper(ctx, principal.DeviceID, principal.ChildID, event)
}

func (s *Service) toGrant(rec grantRecord) Grant {
	remaining := rec.Minutes*60 - rec.ConsumedSeconds
	if remaining < 0 {
		remaining = 0
	}
	token, err := s.signLease(rec)
	if err != nil {
		s.logger.Error("sign lease", "error", err, "grant_id", rec.ID)
	}
	return Grant{
		GrantID:          rec.ID,
		SessionID:        rec.SessionID,
		Minutes:          rec.Minutes,
		ValidFrom:        rec.ValidFrom,
		ValidUntil:       rec.ValidUntil,
		RemainingSeconds: remaining,
		Status:           rec.Status,
		LeaseToken:       token,
	}
}

type leaseClaims struct {
	Type      string `json:"typ"`
	ChildID   string `json:"child_id"`
	DeviceID  string `json:"device_id"`
	SessionID string `json:"session_id"`
	jwt.RegisteredClaims
}

func (s *Service) signLease(rec grantRecord) (string, error) {
	claims := leaseClaims{
		Type:      "grant",
		ChildID:   rec.ChildID,
		DeviceID:  rec.DeviceID,
		SessionID: rec.SessionID,
		RegisteredClaims: jwt.RegisteredClaims{
			Subject:   rec.ID,
			ID:        rec.JTI,
			IssuedAt:  jwt.NewNumericDate(rec.ValidFrom),
			ExpiresAt: jwt.NewNumericDate(rec.ValidUntil),
		},
	}
	return jwt.NewWithClaims(jwt.SigningMethodHS256, claims).SignedString(s.secret)
}

func randomToken() string {
	b := make([]byte, 18)
	if _, err := rand.Read(b); err != nil {
		panic(err)
	}
	return base64.RawURLEncoding.EncodeToString(b)
}

package watch

import (
	"encoding/json"
	"errors"
	"net/http"

	"github.com/go-chi/chi/v5"

	"github.com/roma007/OpenQuizGo/internal/identity"
)

// DeviceRoutes 注册电视端计量与设备上报接口。
func (s *Service) DeviceRoutes(r chi.Router) {
	r.Post("/watch/grants/{grantID}/heartbeat", s.handleHeartbeat)
	r.Get("/watch/grants/active", s.handleActiveGrant)
	r.Put("/device/capability", s.handleCapability)
	r.Post("/device/tamper", s.handleTamper)
}

func (s *Service) handleHeartbeat(w http.ResponseWriter, r *http.Request) {
	principal, ok := identity.DeviceFrom(r.Context())
	if !ok {
		writeWatchError(w, r, newError(401, "AUTH_INVALID_TOKEN", "设备未授权"))
		return
	}
	var req HeartbeatRequest
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeWatchError(w, r, newError(422, "VALIDATION_ERROR", "请求体不是合法 JSON"))
		return
	}
	result, err := s.Heartbeat(r.Context(), principal, chi.URLParam(r, "grantID"), req)
	if err != nil {
		writeWatchError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, result)
}

func (s *Service) handleActiveGrant(w http.ResponseWriter, r *http.Request) {
	principal, ok := identity.DeviceFrom(r.Context())
	if !ok {
		writeWatchError(w, r, newError(401, "AUTH_INVALID_TOKEN", "设备未授权"))
		return
	}
	grant, err := s.ActiveGrant(r.Context(), principal)
	if err != nil {
		writeWatchError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, grant)
}

func (s *Service) handleCapability(w http.ResponseWriter, r *http.Request) {
	principal, ok := identity.DeviceFrom(r.Context())
	if !ok {
		writeWatchError(w, r, newError(401, "AUTH_INVALID_TOKEN", "设备未授权"))
		return
	}
	var capability Capability
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
	if err := json.NewDecoder(r.Body).Decode(&capability); err != nil {
		writeWatchError(w, r, newError(422, "VALIDATION_ERROR", "请求体不是合法 JSON"))
		return
	}
	if err := s.ReportCapability(r.Context(), principal, capability); err != nil {
		writeWatchError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func (s *Service) handleTamper(w http.ResponseWriter, r *http.Request) {
	principal, ok := identity.DeviceFrom(r.Context())
	if !ok {
		writeWatchError(w, r, newError(401, "AUTH_INVALID_TOKEN", "设备未授权"))
		return
	}
	var event TamperEvent
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20)
	if err := json.NewDecoder(r.Body).Decode(&event); err != nil {
		writeWatchError(w, r, newError(422, "VALIDATION_ERROR", "请求体不是合法 JSON"))
		return
	}
	if err := s.ReportTamper(r.Context(), principal, event); err != nil {
		writeWatchError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func writeWatchError(w http.ResponseWriter, r *http.Request, err error) {
	var watchErr *Error
	if errors.As(err, &watchErr) {
		writeJSON(w, watchErr.Status, map[string]string{
			"code":       watchErr.Code,
			"message":    watchErr.Message,
			"request_id": w.Header().Get("X-Request-Id"),
		})
		return
	}
	writeJSON(w, http.StatusInternalServerError, map[string]string{
		"code":       "INTERNAL",
		"message":    "服务端错误",
		"request_id": w.Header().Get("X-Request-Id"),
	})
}

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

